def extract_fields(
    record: dict,
    paths: dict[str, str],
    default=None,
    required: set | None = None,
) -> dict:
    # Input validation
    if not isinstance(record, dict):
        raise TypeError(
            f"'record' must be a dict, got {type(record).__name__!r}"
        )
