        if not isinstance(output_key, str):
            raise TypeError(
                f"All keys in 'paths' must be strings, got {type(output_key).__name__!r}"
            )
        if not isinstance(path, str):
            raise TypeError(
                f"All values in 'paths' must be strings, got {type(path).__name__!r} "
                f"for key {output_key!r}"
            )
        if not path:
            raise ValueError(
                f"Path for key {output_key!r} must not be empty"
            )
    if required is not None and not isinstance(required, (set, frozenset)):
        raise TypeError(
            f"'required' must be a set or None, got {type(required).__name__!r}"
        )

    return {
        output_key: _resolve_output_key(record, output_key, path, default, required)
        for output_key, path in paths.items()
    }

